toolScript:
const CARD_WIDTH_MM = 85.60;
        const VISUAL_ANGLE_TAN = Math.tan((5 / 60) * (Math.PI / 180) / 2) * 2;
        let pixelsPerMm = 0;
        let isVoiceEnabled = false;
        let isSpeechRecActive = false;
        let chartType = 'snellen';
        let isDuochrome = false;
        let isMirror = false;
        let currentEye = 'OU';
        let currentContrast = 1;
        let userXP = 0;
        let userLevel = 1;
        let recognition = null;
        let examResults = { OU: null, OD: null, OS: null };
        let isVoiceExamMode = false;
        let currentExamRow = 0;
        let rowData = [];

        function analyzePrescription() {
            const modal = document.getElementById('rx-modal');
            const container = document.getElementById('rx-results-container');
            container.innerHTML = '';

            if (!examResults.OU && !examResults.OD && !examResults.OS) {
                container.innerHTML = `<div class="p-6 bg-slate-100 rounded-2xl text-center text-slate-500 font-bold">No vision results logged yet. Click lines on the chart or complete a voice exam first.</div>`;
                modal.setAttribute('data-open', 'true');
                modal.classList.remove('hidden');
                return;
            }

            ['OD', 'OS', 'OU'].forEach(eye => {
                if (examResults[eye]) {
                    const denom = examResults[eye];
                    let diopter = 0.00;
                    if (denom > 20) {
                        if (denom <= 30) diopter = -0.50;
                        else if (denom <= 40) diopter = -0.75;
                        else if (denom <= 50) diopter = -1.00;
                        else if (denom <= 60) diopter = -1.25;
                        else if (denom <= 70) diopter = -1.50;
                        else if (denom <= 100) diopter = -1.75;
                        else if (denom <= 200) diopter = -2.50;
                        else diopter = -3.00;
                    }

                    let suggestion = "Excellent vision. No glasses needed.";
                    let color = "bg-green-50 border-green-200 text-green-800";
                    if (diopter <= -0.50 && diopter >= -1.00) {
                        suggestion = "Mild Myopia. Low strength glasses (-0.50D to -1.00D) recommended for driving, watching TV, or seeing distant screens comfortably.";
                        color = "bg-amber-50 border-amber-200 text-amber-800";
                    } else if (diopter <= -1.25 && diopter >= -2.00) {
                        suggestion = "Moderate Myopia. Full-time prescription glasses (-1.25D to -2.00D) or contact lenses recommended for all distance viewing tasks.";
                        color = "bg-orange-50 border-orange-200 text-orange-800";
                    } else if (diopter <= -2.50) {
                        suggestion = "Significant Myopia. Corrective lenses (-2.50D or stronger) are strictly required for driving and functional daily life. Recommend High-Index lenses.";
                        color = "bg-red-50 border-red-200 text-red-800";
                    }

                    const eyeTitle = eye === 'OD' ? 'Right Eye (OD)' : (eye === 'OS' ? 'Left Eye (OS)' : 'Both Eyes (OU)');

                    container.innerHTML += `
                        <div class="p-5 rounded-2xl border ${color} shadow-sm animate-fadeIn">
                            <div class="flex justify-between items-end mb-3">
                                <h4 class="font-black text-lg tracking-tight uppercase">${eyeTitle}</h4>
                                <div class="text-right">
                                    <div class="text-[10px] font-bold uppercase tracking-widest opacity-60 mb-1">Max Acuity</div>
                                    <div class="font-mono font-bold text-xl">20/${denom}</div>
                                </div>
                            </div>
                            <div class="flex flex-col bg-white/50 p-4 rounded-xl border border-white/20 mb-3">
                                <div class="flex items-center justify-between mb-1">
                                    <span class="font-bold text-xs uppercase tracking-widest opacity-80">Lens Power Estimate:</span>
                                    <span class="text-xl font-black font-mono tracking-tighter">${diopter < 0 ? diopter.toFixed(2) : 'PLANO'} ${diopter < 0 ? 'D' : ''}</span>
                                </div>
                                <div class="text-[10px] uppercase font-bold text-slate-500 text-right mt-1">${diopter < 0 ? '(Minus Power for Myopia)' : '(Normal Vision)'}</div>
                            </div>
                            <p class="text-sm leading-relaxed">${suggestion}</p>
                        </div>
                    `;
                }
            });

            modal.classList.remove('hidden');
            setTimeout(() => {
                modal.setAttribute('data-open', 'true');
            }, 10);
        }

        function closeRxModal() {
            const modal = document.getElementById('rx-modal');
            modal.setAttribute('data-open', 'false');
            setTimeout(() => {
                modal.classList.add('hidden');
            }, 300);
        }
        // Optotype Definitions
        const OPTOTYPES = {
            'snellen': ['C', 'D', 'E', 'F', 'L', 'N', 'O', 'P', 'T', 'Z'],
            'sloan': ['C', 'D', 'H', 'K', 'N', 'O', 'R', 'S', 'V', 'Z'],
            'tumbling': ['E', 'ш', 'ヨ', 'п']
        };
        const LEVEL_TITLES = [
            "Novice Observer", "Keen Sighter", "Eagle Eye", "Precision Scout",
            "Optical Master", "Visionary", "Hawkeye", "Apex Seer", "Clinical Standard", "20/10 Legend"
        ];
        // --- Core Functions ---
        function toggleDarkMode() {
            document.body.classList.toggle('dark-mode');
        }
        function syncDistanceInput() {
            const select = document.getElementById('distance-select');
            const custom = document.getElementById('custom-distance');
            if (select.value === 'custom') {
                custom.classList.remove('hidden');
            } else {
                custom.classList.add('hidden');
                custom.value = select.value;
            }
        }
        function getDistance() {
            const select = document.getElementById('distance-select');
            const custom = document.getElementById('custom-distance');
            return select.value === 'custom' ? parseFloat(custom.value) : parseFloat(select.value);
        }
        function updateCardSize() {
            const val = document.getElementById('cal-slider').value;
            const box = document.getElementById('card-box');
            box.style.width = val + 'px';
            box.style.height = (val * 0.628) + 'px';
        }
        function finishCalibration() {
            const pixelWidth = parseInt(document.getElementById('card-box').style.width);
            pixelsPerMm = pixelWidth / CARD_WIDTH_MM;
            document.getElementById('calibration-step').classList.add('hidden');
            document.getElementById('gamification-header').classList.remove('hidden');
            document.getElementById('test-controls').classList.remove('hidden');
            document.getElementById('chart-view').classList.remove('hidden');
            document.getElementById('session-log').classList.remove('hidden');
            if (!localStorage.getItem('tutorialSeen')) {
                setTimeout(startTutorial, 500);
            }
            renderChart();
            window.scrollTo({ top: document.querySelector('.tool-card').offsetTop - 50, behavior: 'smooth' });
        }
        function setChartType(type) {
            chartType = type;
            const selectEl = document.getElementById('chart-select');
            if (selectEl) selectEl.value = type;
            renderChart();
        }
        function setDuochrome(active) {
            isDuochrome = active;
            const selectEl = document.getElementById('duo-select');
            if (selectEl) selectEl.value = active.toString();
            document.getElementById('chart-view').classList.toggle('duochrome-mode', active);
        }
        function setEye(eye) {
            currentEye = eye;
            const selectEl = document.getElementById('eye-select');
            if (selectEl) selectEl.value = eye;
        }
        function setContrast(val) {
            currentContrast = val;
            const selectEl = document.getElementById('contrast-select');
            if (selectEl) selectEl.value = val.toString();
            renderChart();
        }
        function printReport() {
            window.print();
        }
        function toggleMirror() {
            setMirror(!isMirror);
        }
        function setMirror(active) {
            isMirror = active;
            const selectEl = document.getElementById('mirror-select');
            if (selectEl) selectEl.value = isMirror.toString();
            document.getElementById('chart-view').classList.toggle('mirror-mode', isMirror);
        }
        function toggleFullscreen() {
            const container = document.getElementById('chart-view');
            if (!document.fullscreenElement) {
                container.requestFullscreen().catch(() => { });
            } else {
                document.exitFullscreen();
            }
        }
        function applyPreset(mode) {
            if (mode === 'clinical') {
                document.getElementById('distance-select').value = "6";
                if (isMirror) toggleMirror();
                setDuochrome(false);
                setChartType('snellen');
                setEye('OU');
                setContrast(1);
            } else if (mode === 'personal') {
                document.getElementById('distance-select').value = "3";
                if (isMirror) toggleMirror();
                setDuochrome(false);
                setChartType('sloan');
                setEye('OU');
                setContrast(1);
            }
            syncDistanceInput();
            renderChart();
        }
        // --- Speech Recognition ---
        function toggleSpeechRec(isExamMode = false) {
            if (!('webkitSpeechRecognition' in window)) {
                alert("Speech recognition is not supported in this browser. Try Chrome.");
                return;
            }
            const btn = document.getElementById('mic-btn');
            const txt = document.getElementById('mic-text');
            const examBtn = document.getElementById('exam-btn');

            if (isSpeechRecActive) {
                recognition.stop();
                isSpeechRecActive = false;
                if (btn) btn.classList.remove('listening-active');
                if (txt) txt.innerText = "Voice Input";
                if (isVoiceExamMode) {
                    isVoiceExamMode = false;
                    document.getElementById('exam-overlay').classList.add('hidden');
                    if (examBtn) {
                        examBtn.classList.remove('listening-active');
                        examBtn.querySelector('span').innerText = "Start Voice Exam";
                    }
                    clearExamHighlights();
                    analyzePrescription();
                }
            } else {
                isVoiceExamMode = isExamMode;
                recognition = new webkitSpeechRecognition();
                recognition.continuous = true;
                recognition.interimResults = false;
                recognition.lang = 'en-US';
                recognition.onstart = function () {
                    isSpeechRecActive = true;
                    if (isExamMode) {
                        if (examBtn) {
                            examBtn.classList.add('listening-active');
                            examBtn.querySelector('span').innerText = "Listening...";
                        }
                        document.getElementById('exam-overlay').classList.remove('hidden');
                        currentExamRow = 0;
                        highlightExamRow();
                    } else {
                        if (btn) btn.classList.add('listening-active');
                        if (txt) txt.innerText = "Listening...";
                    }
                };
                recognition.onresult = function (event) {
                    const lastResult = event.results[event.results.length - 1];
                    let rawText = lastResult[0].transcript.toUpperCase().trim();

                    rawText = rawText.replace(/\bSEE\b/g, 'C').replace(/\bSEA\b/g, 'C').replace(/\bDEE\b/g, 'D')
                        .replace(/\bBEE\b/g, 'B').replace(/\bPEA\b/g, 'P').replace(/\bTEE\b/g, 'T')
                        .replace(/\bTEA\b/g, 'T').replace(/\bVE\b/g, 'V').replace(/\bZEE\b/g, 'Z')
                        .replace(/\bZED\b/g, 'Z').replace(/\bOH\b/g, 'O').replace(/\bARE\b/g, 'R')
                        .replace(/\bYOU\b/g, 'U').replace(/\bKAY\b/g, 'K').replace(/\bEFF\b/g, 'F')
                        .replace(/\bESS\b/g, 'S').replace(/\bACHE\b/g, 'H').replace(/\bEIGHT\b/g, 'H')
                        .replace(/\bSI\b/g, 'C').replace(/\bUP\b/g, 'ш').replace(/\bDOWN\b/g, 'п')
                        .replace(/\bLEFT\b/g, 'ヨ').replace(/\bRIGHT\b/g, 'E');

                    const text = rawText.split(' ').join('');

                    if (isVoiceExamMode) {
                        if (rawText.includes('STOP') || rawText.includes('DONE') || rawText.includes('FINISH')) {
                            toggleSpeechRec();
                            return;
                        }
                        if (rawText.includes('SKIP') || rawText.includes('NEXT') || rawText.includes('NO')) {
                            currentExamRow++;
                            highlightExamRow();
                            return;
                        }
                        processExamVoice(text);
                    } else {
                        highlightSpokenLetters(text);
                    }
                };
                recognition.onend = function () {
                    if (isSpeechRecActive) recognition.start();
                }
                recognition.start();
            }
        }

        function startVoiceExam() {
            if (!isSpeechRecActive) {
                clearHistory();
                examResults = { OU: null, OD: null, OS: null };

                if ('speechSynthesis' in window) {
                    const msg = new SpeechSynthesisUtterance("Starting Voice Exam. Please read the highlighted line. Say stop if you cannot see the letters.");
                    msg.onend = () => { toggleSpeechRec(true); };
                    window.speechSynthesis.speak(msg);

                    const examBtn = document.getElementById('exam-btn');
                    examBtn.querySelector('span').innerText = "Speaking Instructions...";
                    examBtn.classList.add('listening-active');
                } else {
                    toggleSpeechRec(true);
                }
            } else if (isVoiceExamMode) {
                toggleSpeechRec();
            } else {
                toggleSpeechRec();
                setTimeout(() => startVoiceExam(), 200);
            }
        }

        function highlightExamRow() {
            clearExamHighlights();
            if (currentExamRow < rowData.length) {
                const targetRowDiv = document.getElementById(`row-${currentExamRow}`);
                if (targetRowDiv) {
                    targetRowDiv.classList.add('ring-4', 'ring-indigo-500', 'ring-offset-8', 'rounded-2xl', 'bg-indigo-50', 'transition-all');
                    const spans = targetRowDiv.querySelectorAll('.optotype');
                    spans.forEach(span => span.dataset.read = 'false');
                }
            } else {
                toggleSpeechRec();
            }
        }

        function clearExamHighlights() {
            document.querySelectorAll('.optotype-row').forEach(row => {
                row.classList.remove('ring-4', 'ring-indigo-500', 'ring-offset-8', 'rounded-2xl', 'bg-indigo-50', 'transition-all');
            });
        }

        function processExamVoice(inputString) {
            if (currentExamRow >= rowData.length) return;
            const targetRowDiv = document.getElementById(`row-${currentExamRow}`);
            const spans = targetRowDiv.querySelectorAll('.optotype');
            let readCount = 0;
            let availableChars = inputString.split('');

            spans.forEach(span => {
                const charIndex = availableChars.indexOf(span.innerText);
                if (charIndex !== -1 && span.dataset.read !== 'true') {
                    span.dataset.read = 'true';
                    span.style.color = "#4f46e5";
                    span.style.transform = "scale(1.3)";
                    setTimeout(() => { span.style.transform = ""; }, 500);
                    availableChars.splice(charIndex, 1);
                }
                if (span.dataset.read === 'true') {
                    readCount++;
                }
            });

            const requiredToPass = Math.floor(spans.length / 2) + 1;
            if (readCount >= requiredToPass) {
                markLine(`20/${rowData[currentExamRow].val}`);
                currentExamRow++;
                highlightExamRow();
            }
        }

        function highlightSpokenLetters(inputString) {
            const spans = document.querySelectorAll('.optotype');
            let availableChars = inputString.split('');
            spans.forEach(span => {
                const charIndex = availableChars.indexOf(span.innerText);
                if (charIndex !== -1) {
                    span.style.color = "#059669";
                    span.style.transform = "scale(1.2)";
                    setTimeout(() => { span.style.color = ""; span.style.transform = ""; }, 2000);
                    availableChars.splice(charIndex, 1);
                }
            });
        }
        function getRandomLetters(count) {
            let res = [];
            const list = OPTOTYPES[chartType];
            for (let i = 0; i < count; i++) {
                res.push(list[Math.floor(Math.random() * list.length)]);
            }
            return res.join(' ');
        }
        // --- Gamification ---
        function addXP(amount) {
            userXP += amount;
            if (userXP >= 100) {
                userXP = 0;
                userLevel = Math.min(userLevel + 1, 10);
                triggerConfetti();
            }
            document.getElementById('xp-bar').style.width = `${userXP}%`;
            document.getElementById('xp-text').innerText = `${userXP} / 100 XP`;
            document.getElementById('level-display').innerText = `${LEVEL_TITLES[userLevel - 1]} (Lvl ${userLevel})`;
        }
        function markLine(label) {
            const grid = document.getElementById('results-grid');
            const eyeLabel = currentEye === 'OU' ? 'Both Eyes (OU)' : (currentEye === 'OD' ? 'Right Eye (OD)' : 'Left Eye (OS)');
            const contrastLabel = currentContrast < 1 ? ` at ${Math.round(currentContrast * 100)}% Contrast` : '';
            const fullText = `${eyeLabel}: ${label}${contrastLabel}`;
            const chipId = `chip-${Date.now()}`;
            const chip = document.createElement('div');
            chip.id = chipId;
            chip.className = "bg-teal-500 text-white px-3 py-1 rounded-full text-[10px] font-black animate-pop cursor-pointer hover:bg-red-500 hover:text-white transition";
            chip.innerText = fullText;
            chip.onclick = () => { chip.remove(); };
            grid.appendChild(chip);
            addXP(20);

            const denom = parseInt(label.split('/')[1]);
            if (!examResults[currentEye] || denom < examResults[currentEye]) {
                examResults[currentEye] = denom;
            }

            if (label === '20/20' || label === '20/15') triggerConfetti();
        }
        function clearHistory() {
            document.getElementById('results-grid').innerHTML = '';
            examResults = { OU: null, OD: null, OS: null };
        }
        function triggerConfetti() {
            const canvas = document.getElementById('confetti');
            const ctx = canvas.getContext('2d');
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            const particles = Array.from({ length: 100 }, () => ({
                x: window.innerWidth / 2, y: window.innerHeight / 2,
                vx: (Math.random() - 0.5) * 20, vy: (Math.random() - 0.5) * 20,
                color: `hsl(${Math.random() * 360}, 70%, 50%)`, life: 1.0
            }));
            function animate() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                let active = false;
                particles.forEach(p => {
                    if (p.life > 0) {
                        p.x += p.vx; p.y += p.vy; p.vy += 0.5; p.life -= 0.02;
                        ctx.globalAlpha = p.life; ctx.fillStyle = p.color;
                        ctx.beginPath(); ctx.arc(p.x, p.y, 5, 0, Math.PI * 2); ctx.fill();
                        active = true;
                    }
                });
                if (active) requestAnimationFrame(animate);
                else ctx.clearRect(0, 0, canvas.width, canvas.height);
            }
            animate();
        }
        // --- Tutorial System V2 (Box Shadow Spotlight) ---
        let tourIndex = 0;
        const tourSteps = [
            { el: 'calibration-step', title: "Calibration", text: "Use a credit card to size the screen accurately." },
            { el: 'tour-distance', title: "Set Distance", text: "Select your viewing distance. 3 meters (10ft) is standard." },
            { el: 'mic-btn', title: "Voice Control", text: "Enable microphone to read letters aloud!" },
            { el: 'chart-view', title: "The Chart", text: "Click any line to log your score." }
        ];
        function startTutorial() {
            tourIndex = 0;
            document.body.classList.add('tutorial-mode');
            document.getElementById('tutorial-card').classList.add('visible');
            showTourStep();
        }
        function endTutorial() {
            document.body.classList.remove('tutorial-mode');
            document.getElementById('tutorial-card').classList.remove('visible');
            document.querySelectorAll('.tutorial-active-element').forEach(el => el.classList.remove('tutorial-active-element'));
            localStorage.setItem('tutorialSeen', 'true');
        }
        function nextTourStep() {
            tourIndex++;
            if (tourIndex >= tourSteps.length) endTutorial();
            else showTourStep();
        }
        function showTourStep() {
            document.querySelectorAll('.tutorial-active-element').forEach(el => el.classList.remove('tutorial-active-element'));
            const step = tourSteps[tourIndex];
            const target = document.getElementById(step.el);
            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            target.classList.add('tutorial-active-element');
            document.getElementById('tour-title').innerText = step.title;
            document.getElementById('tour-desc').innerText = step.text;
            document.getElementById('tour-step').innerText = `Step ${tourIndex + 1}`;
        }
        // --- Render Logic ---
        function renderChart() {
            if (pixelsPerMm === 0) return;
            const distanceMm = getDistance() * 1000;
            const baseHeightMm = distanceMm * VISUAL_ANGLE_TAN;
            const container = document.getElementById('chart-view');
            container.innerHTML = '';
            const rows = [
                { val: 200, count: 1 }, { val: 100, count: 2 }, { val: 70, count: 3 },
                { val: 50, count: 4 }, { val: 40, count: 5 }, { val: 30, count: 6 },
                { val: 25, count: 7 }, { val: 20, count: 8 }, { val: 15, count: 8 }, { val: 10, count: 9 }
            ];
            rowData = rows;
            const maxAvailableWidth = container.clientWidth * 0.90;
            rows.forEach((row, index) => {
                const heightMm = baseHeightMm * (row.val / 20);
                let heightPx = heightMm * pixelsPerMm;
                // Calculate LogMAR and Decimal for Clinical Info
                const logMAR = Math.log10(row.val / 20).toFixed(1);
                const decimal = (20 / row.val).toFixed(2);
                // Dynamic scaling to fit width
                const estimatedWidth = heightPx * row.count * 1.3;
                if (estimatedWidth > maxAvailableWidth) heightPx = maxAvailableWidth / (row.count * 1.3);
                const rowDiv = document.createElement('div');
                rowDiv.className = 'optotype-row w-full group transition-all duration-300';
                rowDiv.id = `row-${index}`;
                rowDiv.style.fontSize = heightPx + 'px';
                const label = document.createElement('div');
                label.className = 'acuity-label cursor-pointer hover:scale-110 transition-transform pointer-events-auto';
                label.innerHTML = `20/${row.val}<br><span class="text-slate-400 text-[8px]">Log: ${logMAR}</span>`;
                label.style.lineHeight = '1.2';
                label.onclick = () => markLine(`20/${row.val}`);
                rowDiv.appendChild(label);
                const letters = getRandomLetters(row.count);
                letters.split(' ').forEach(char => {
                    const span = document.createElement('span');
                    span.className = 'optotype mx-1';
                    span.innerText = char;
                    span.style.opacity = currentContrast;
                    if (chartType === 'tumbling') {
                        // Random rotate for E chart
                        // We already select rotated chars in list, but we can do CSS rotation too if needed
                        // Current list ['E', 'ш', 'ヨ', 'п'] handles rotation via glyphs
                    }
                    rowDiv.appendChild(span);
                });
                container.appendChild(rowDiv);
            });
        }
        function randomizeChart() { renderChart(); }
        updateCardSize();
        let resizeTimer;
        window.addEventListener('resize', () => {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(() => renderChart(), 200);
        });
